class binary_tree {
public:
    explicit binary_tree(const T& data) : data_(data) {}

    const T& data() const { return data_; }

    const std::unique_ptr<binary_tree<T>>& left() const { return left_; }
    const std::unique_ptr<binary_tree<T>>& right() const { return right_; }

    void insert(const T& value) {
        if (value <= data_) {
            if (!left_) {
                left_ = std::make_unique<binary_tree<T>>(value);
                left_->parent_ = this;
            } else {
                left_->insert(value);
            }
        } else {
            if (!right_) {
                right_ = std::make_unique<binary_tree<T>>(value);
                right_->parent_ = this;
            } else {
                right_->insert(value);
            }
        }
    }

    class iterator {
    public:
        using iterator_category = std::input_iterator_tag;
        using value_type = T;
        using difference_type = std::ptrdiff_t;
        using pointer = const T*;
        using reference = const T&;

        iterator() = default;
        explicit iterator(const binary_tree<T>* tree) : node_(tree) {
            advance();
        }

        reference operator*() const { return node_->data_; }
        pointer operator->() const { return &node_->data_; }

        iterator& operator++() {
            next();
            return *this;
        }

        iterator operator++(int) {
            iterator tmp = *this;
            ++(*this);
            return tmp;
        }

        bool operator==(const iterator& other) const {
            return node_ == other.node_;
        }

        bool operator!=(const iterator& other) const {
            return node_ != other.node_;
        }

    private:
        friend class binary_tree<T>;

        // Move to the leftmost node of the subtree rooted at node_.
        void advance() {
            while (node_ && node_->left_) {
                node_ = node_->left_.get();
            }
        }

        void next() {
            if (!node_) return;
            if (node_->right_) {
                node_ = node_->right_.get();
                advance();
            } else {
                node_ = node_->parent_;
            }
        }

        const binary_tree<T>* node_ = nullptr;
    };

    iterator begin() { return iterator(this); }
    iterator end() { return iterator(nullptr); }

private:
    friend class iterator;

    T data_;
    std::unique_ptr<binary_tree<T>> left_;
    std::unique_ptr<binary_tree<T>> right_;
    const binary_tree<T>* parent_ = nullptr;
};

}  // namespace binary_search_tree

